insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$tres-lagoas$q$, $q$https://www.diariomunicipal.com.br/ms/materia/3FCD7B99 (Decreto 141/2011) ; https://www.diariomunicipal.com.br/ms/materia/933397B9 (Decreto 154/2011, vigência) ; https://www.diariomunicipal.com.br/ms/materia/17BB1F4A (Decreto 140/2012)$q$, $q$Atos oficiais de Três Lagoas: domínio público (Lei 9.610/1998, art. 8º, IV). Polígono montado sobre as vias do OpenStreetMap (PBF local): derivado do OSM, ODbL 1.0 (© colaboradores do OpenStreetMap), base derivada separada do OSM.$q$, 1, $q$Decreto 141/2011 (arts. 1º-5º), em vigor 40 dias após a publicação (Dec. 154/2011), com o art. 1º e o art. 4º alterados pelo Decreto 140/2012: caminhões de carga com PBT acima de 12 t proibidos no quadrilátero central (24 h); carga e descarga num perímetro proibida 9h-17h seg-sex e 9h-14h sáb (desativada: não é circulação). Confiança média: o diário ASSOMASUL não cobre Três Lagoas depois de 2019 e leismunicipais/leis.org estavam bloqueados, então alteração posterior não pôde ser excluída.$q$);
